import React from "react";
import Info from "./components/info.js"
import Form from "./components/form.js"
import Place from "./components/place.js"
import Footer from "./components/Footer.js"

const API_KEY = "e5832fe7fa724f039e8a644e5697a808";

class App extends React.Component {
  state = {
    temp: undefined,
    ip: undefined,
    city: undefined,
    country_name: undefined,
    state_prov: undefined,
    hostname: undefined,
    error: undefined,
}
}
class Menu extends React.Component{
  render(){
    let menus = [
      "History"
    ]
    return <div>
    {menus.map((value, index, list)=>{
      return <div key={index}><Link label={value} /></div>
    })}
    </div>
  }
}
class Link extends React.Component{
  render(){
 const url = "/" + this.props.label.toLowerCase().trim().replace(" ", "-");
 return<div>
 <a href={url}>{this.props.label}</a>
 </div>
}
  gettingPlace = async (e) => {
    e.preventDefault();
    const Ip = e.target.elements.ip.value;
    const api_url = await
    fetch(`https://api.ipgeolocation.io/ipgeo?apiKey=${API_KEY}&ip=${Ip}&appid`);
    const data = await api_url.json();
    console.log(data);

    if(Ip){
    this.setState({
      ip: data.ip,
      city: data.city,
      country_name: data.country_name,
      state_prov: data.state_prov,
      hostname: data.hostname,
      error:""
    });
  }
}
render(){
    return (
      <div className="App">
        <Info />
        <Menu />
        <Footer />
        <Form placeIp={this.gettingPlace} />
        <Place
          ip={this.state.ip}
          city={this.state.city}
          country_name={this.state.country_name}
          state_prov={this.state.state_prov}
          hostname={this.state.hostname}
          error={this.state.error}
         />
      </div>
    );
  }
}
export default App;
